<?php $root='../../';require '../../includes/header.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$f=fopen($_FILES['archivo']['tmp_name'],'r');fgetcsv($f);$n=0;$sql="INSERT INTO beneficiarios(tipo_documento,documento,nombre,ficha,programa,estado,fecha_ingreso) VALUES(?,?,?,?,?,'Activo',CURDATE()) ON DUPLICATE KEY UPDATE nombre=VALUES(nombre),ficha=VALUES(ficha),programa=VALUES(programa)";$s=$pdo->prepare($sql);while(($x=fgetcsv($f))!==false){if(count($x)>=5&&trim($x[1])!==''){$s->execute(array_slice($x,0,5));$n++;}}fclose($f);$msg="$n registros procesados.";}?><h2>Carga CSV</h2><?php if($msg):?><div class="alert alert-success"><?=$msg?></div><?php endif?><form method="post" enctype="multipart/form-data" class="card p-4 mt-3"><p>Columnas: TIPO_DOCUMENTO, DOCUMENTO, NOMBRE, FICHA, PROGRAMA.</p><input required type="file" name="archivo" accept=".csv" class="form-control"><button class="btn btn-primary mt-3">Importar</button><a class="btn btn-link" href="plantilla.csv">Descargar plantilla</a></form><?php require '../../includes/footer.php';?>